-- Tour and model publications have separate current snapshots. Never fall back
-- to an older snapshot when the latest of that kind is revoked. Preserve all
-- existing source, reviewer, consent, scope and public-listing checks.
CREATE OR REPLACE FUNCTION digitization_public_package_context_base(listing_ref uuid,package_ref uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE pkg published_packages;p digitization_publication_proposals;q digitization_tour_review_requests;author_roles text[];
BEGIN
 SELECT * INTO pkg FROM published_packages WHERE listing_id=listing_ref AND manifest->>'viewerType'='panorama' ORDER BY publication_number DESC LIMIT 1;
 IF pkg.id IS NULL OR package_ref IS NOT NULL AND package_ref<>pkg.id OR EXISTS(SELECT 1 FROM digitization_package_revocations WHERE package_id=pkg.id) OR NOT EXISTS(SELECT 1 FROM listings WHERE id=listing_ref AND status='published') THEN RETURN NULL;END IF;
 SELECT * INTO p FROM digitization_publication_proposals WHERE listing_revision_id=pkg.listing_revision_id;SELECT * INTO q FROM digitization_tour_review_requests WHERE id=p.tour_review_request_id;
 IF p.id IS NULL OR NOT digitization_actor_target(p.created_by,p.organization_id,p.created_by,'listing',listing_ref,(SELECT unit_id FROM listings WHERE id=listing_ref)) OR NOT EXISTS(SELECT 1 FROM profiles pr JOIN memberships m ON m.user_id=pr.id JOIN organizations o ON o.id=m.organization_id WHERE pr.id=p.created_by AND pr.state='active' AND m.organization_id=p.organization_id AND m.status='active' AND m.role IN('agent','agency_manager') AND o.type='agency') OR NOT EXISTS(SELECT 1 FROM approval_records WHERE id=pkg.approval_id AND decision='approved' AND scope='package') THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(q.sources) s LEFT JOIN media_assets a ON a.id=(s->>'assetId')::uuid WHERE a.id IS NULL OR a.owner_id<>p.created_by OR a.status<>'approved' OR a.visibility<>'private' OR a.scan_at IS NULL OR a.version<>(s->>'assetVersion')::int OR a.size::text IS DISTINCT FROM s->>'bytes' OR a.mime IS DISTINCT FROM s->>'detectedMime') THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM digitization_public_package_bindings b LEFT JOIN artifacts a ON a.id=b.artifact_id JOIN processing_stages st ON st.id=a.stage_id WHERE b.package_id=pkg.id AND (a.status<>'private' OR a.privacy_status NOT IN('pending','passed') OR a.format<>'image/png' OR st.state<>'succeeded' OR a.digitization_id<>pkg.digitization_id OR a.input_revision<>pkg.input_revision)) THEN RETURN NULL;END IF;
 SELECT array_agg(DISTINCT role) INTO author_roles FROM memberships WHERE user_id=p.created_by AND organization_id=p.organization_id AND status='active' AND role IN('agent','agency_manager');
 RETURN jsonb_build_object('packageId',pkg.id,'version',pkg.version,'publicationNumber',pkg.publication_number,'manifest',pkg.manifest,'engineId',pkg.digitization_id,'author',jsonb_build_object('id',p.created_by,'orgId',p.organization_id,'roles',to_jsonb(author_roles)),'sources',q.sources,'inputRevision',pkg.input_revision,'bindings',(SELECT jsonb_agg(jsonb_build_object('nodeSlot',b.node_slot,'tierSlot',b.tier_slot,'artifactId',b.artifact_id)) FROM digitization_public_package_bindings b WHERE b.package_id=pkg.id));
END $$;
CREATE OR REPLACE FUNCTION digitization_public_model(listing_ref uuid,package_ref uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE pkg published_packages;p digitization_model_publication_proposals;q digitization_model_review_requests;roles text[];
BEGIN
 SELECT * INTO pkg FROM published_packages WHERE listing_id=listing_ref AND manifest->>'viewerType' IN('structural','splat') ORDER BY publication_number DESC LIMIT 1;
 IF pkg.id IS NULL OR pkg.manifest->>'viewerType' NOT IN('structural','splat') OR (package_ref IS NOT NULL AND package_ref<>pkg.id) OR EXISTS(SELECT 1 FROM digitization_package_revocations WHERE package_id=pkg.id) OR NOT EXISTS(SELECT 1 FROM public_listings WHERE id=listing_ref) THEN RETURN NULL;END IF;
 SELECT * INTO p FROM digitization_model_publication_proposals WHERE listing_revision_id=pkg.listing_revision_id;SELECT * INTO q FROM digitization_model_review_requests WHERE id=p.model_review_request_id;
 IF p.id IS NULL OR q.id IS NULL OR NOT p.publication_consent_confirmed OR NOT EXISTS(SELECT 1 FROM property_digitizations WHERE id=p.digitization_id AND state='active') OR NOT digitization_actor_target(p.created_by,p.organization_id,p.created_by,'listing',listing_ref,(SELECT unit_id FROM listings WHERE id=listing_ref)) OR NOT EXISTS(SELECT 1 FROM profiles pr JOIN memberships m ON m.user_id=pr.id JOIN organizations o ON o.id=m.organization_id WHERE pr.id=p.created_by AND pr.state='active' AND m.organization_id=p.organization_id AND m.status='active' AND m.role IN('agent','agency_manager') AND o.type='agency') THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM approval_records pa JOIN approval_records a ON a.id=p.approval_id WHERE pa.id=pkg.approval_id AND pa.scope='package' AND pa.decision='approved' AND pa.snapshot->>'modelProposalId'=p.id::text AND pa.snapshot->>'candidateChecksum'=q.candidate_checksum AND a.decision='approved' AND a.snapshot->>'modelReviewRequestId'=q.id::text AND a.snapshot->'privacyConfirmed'='true'::jsonb AND a.snapshot->'limitationsConfirmed'='true'::jsonb AND NOT EXISTS(SELECT 1 FROM digitization_approval_invalidations i WHERE i.approval_id IN(pa.id,a.id) AND i.input_revision<=pkg.input_revision)) OR pkg.manifest<>digitization_model_manifest(q.model_type,q.candidate_checksum) THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(q.sources) source LEFT JOIN media_assets a ON a.id=(source->>'assetId')::uuid WHERE a.id IS NULL OR NOT digitization_model_source_authority(p.created_by,p.digitization_id,a.id,a.version,p.input_revision,'model_publication') OR a.status<>'approved' OR a.visibility<>'private' OR a.scan_at IS NULL OR a.version IS DISTINCT FROM (source->>'assetVersion')::integer OR a.size::text IS DISTINCT FROM source->>'bytes' OR a.mime IS DISTINCT FROM source->>'detectedMime') THEN RETURN NULL;END IF;
 IF q.model_type='splat' AND NOT EXISTS(SELECT 1 FROM artifacts ar JOIN processing_stages stage ON stage.id=ar.stage_id WHERE ar.id=q.scene_artifact_id AND ar.digitization_id=p.digitization_id AND ar.input_revision=p.input_revision AND ar.version=q.scene_artifact_version AND ar.checksum=q.scene_artifact_checksum AND ar.status='private' AND ar.format='application/octet-stream' AND stage.state='succeeded' AND stage.stage_type='scene_export') THEN RETURN NULL;END IF;
 SELECT array_agg(DISTINCT role) INTO roles FROM memberships WHERE user_id=p.created_by AND organization_id=p.organization_id AND status='active' AND role IN('agent','agency_manager');
 RETURN jsonb_build_object('packageId',pkg.id,'version',pkg.version,'publicationNumber',pkg.publication_number,'manifest',pkg.manifest,'engineId',pkg.digitization_id,'inputRevision',pkg.input_revision,'request',to_jsonb(q),'author',jsonb_build_object('id',p.created_by,'orgId',p.organization_id,'roles',to_jsonb(roles)));
END $$;
CREATE OR REPLACE FUNCTION digitization_revoke_package(package_ref uuid,expected int,reason_ref text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE p published_packages;
BEGIN
 SELECT * INTO p FROM published_packages WHERE id=package_ref;
 IF p.id IS NULL OR expected<>p.version OR NOT digitization_target_access(p.digitization_id) OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=actor_id() AND state='active') THEN RAISE EXCEPTION 'Current publication authority and version required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM listings WHERE id=p.listing_id FOR UPDATE;
 IF p.id<>(SELECT id FROM published_packages WHERE listing_id=p.listing_id AND (manifest->>'viewerType'='panorama')=(p.manifest->>'viewerType'='panorama') ORDER BY publication_number DESC LIMIT 1) OR EXISTS(SELECT 1 FROM digitization_package_revocations WHERE package_id=p.id) THEN RAISE EXCEPTION 'Current active package required' USING ERRCODE='40001';END IF;
 INSERT INTO digitization_package_revocations(package_id,created_by,package_version,reason) VALUES(p.id,actor_id(),expected,reason_ref);RETURN p.id;
END $$;
